"""The table-based value learner (AGENT-01, AGENT-02, ABL-03)."""

from pathlib import Path

import numpy as np

from rllab.agents.dqn.agent import epsilon
from rllab.core import Agent, AgentParams, Exploration, Transition


class TabularAgent(Agent):
    """One value per (observation, action), keyed on the observation's bytes."""

    def __init__(
        self,
        n_actions: int,
        params: AgentParams,
        exploration: Exploration,
        *,
        seed: int,
        explore_enabled: bool = True,
    ) -> None:
        self._n_actions = n_actions
        self._params = params
        self._exploration = exploration
        self._explore_enabled = explore_enabled
        self._rng = np.random.default_rng(seed)
        self._table: dict[bytes, np.ndarray] = {}
        self._steps = 0

    def _row(self, obs: np.ndarray) -> np.ndarray:
        """The values of one agent's observation, all 0 if never seen (not stored)."""
        return self._table.get(obs.tobytes(), np.zeros(self._n_actions))

    def value(self, obs: np.ndarray, action: int) -> float:
        """The learned value of `action` for one agent's observation, 0.0 if never learned."""
        return float(self._row(obs)[action])

    def exploration_rate(self, step: int) -> float:
        """The exploration rate after `step` learn calls (AGENT-02)."""
        if step < 0:
            raise ValueError(f"exploration step must not be negative, got {step}")
        return epsilon(self._exploration, step)

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        """Agent 0's action: random at the current rate if exploring and enabled, else argmax."""
        rate = self.exploration_rate(self._steps)
        if explore and self._explore_enabled and self._rng.random() < rate:
            return np.array([self._rng.integers(self._n_actions)], dtype=np.int64)
        return np.array([int(np.argmax(self._row(obs[0])))], dtype=np.int64)

    def learn(self, t: Transition) -> None:
        """Move agent 0's value toward `reward + gamma * max next value`; no bootstrap at its end."""
        self._steps += 1
        if not t.active[0]:
            return
        key = t.obs[0].tobytes()
        row = self._table.setdefault(key, np.zeros(self._n_actions))
        bootstrap = 0.0 if t.terminated[0] else float(np.max(self._row(t.next_obs[0])))
        target = float(t.reward[0]) + self._params.gamma * bootstrap
        action = int(t.actions[0])
        row[action] += self._params.lr * (target - row[action])

    def save(self, path: Path) -> None:
        """Write the table (keys as byte rows, values) and the learn-call count as NPZ."""
        keys = [np.frombuffer(k, dtype=np.uint8) for k in self._table]
        np.savez(
            path,
            keys=np.stack(keys) if keys else np.zeros((0, 0), dtype=np.uint8),
            values=np.array(list(self._table.values())).reshape(-1, self._n_actions),
            steps=np.array(self._steps),
        )

    def load(self, path: Path) -> None:
        """Read a table and learn-call count written by `save`."""
        with np.load(path) as checkpoint:
            keys = checkpoint["keys"]
            values = checkpoint["values"]
            self._steps = int(checkpoint["steps"])
        self._table = {k.tobytes(): v.copy() for k, v in zip(keys, values, strict=True)}

